package me.kright.gametools.pga3d

import scala.annotation.targetName
import me.kright.gametools.flatarray.FlatDoubleSerializer


/**
 * A point with four homogeneous coordinates: (x/w, y/w, z/w) when w != 0, or an ideal point (a direction) when w == 0.
 * The grade-3 element of 3d PGA, stored in dual representation.
 *
 * Variable fields: x, y, z, w.
 * Basis blade coefficients: wyz = -x, wxz = y, wxy = -z, xyz = w.
 *
 * Generated by pgaNdCodeGen (me.kright.gametools.pga.codegen.scalagen.pga3d.runScalaCodeGen).
 * Do not edit by hand: change the generator and re-run it.
 */
final case class Pga3dProjectivePoint(x: Double = 0.0,
                                      y: Double = 0.0,
                                      z: Double = 0.0,
                                      w: Double = 0.0) derives CanEqual, FlatDoubleSerializer:

  inline def wyz: Double = -x

  inline def wxz: Double = y

  inline def wxy: Double = -z

  inline def xyz: Double = w

  override def toString: String =
    s"Pga3dProjectivePoint(x = $x, y = $y, z = $z, w = $w)"

  def dual: Pga3dPlane =
    Pga3dPlane(
      x = x,
      y = y,
      z = z,
      w = w,
    )

  def weight: Pga3dVector =
    Pga3dVector(
      x = x,
      y = y,
      z = z,
    )

  def bulk: Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = 0.0,
      y = 0.0,
      z = 0.0,
      w = w,
    )

  @targetName("unaryMinus")
  def unary_- : Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = -x,
      y = -y,
      z = -z,
      w = -w,
    )

  def reverse: Pga3dProjectivePoint =
    -this

  def antiReverse: Pga3dProjectivePoint =
    this

  def bulkNormSquare: Double =
    w * w

  def bulkNorm: Double =
    Math.sqrt(bulkNormSquare)

  def normalizedByBulk =
    this / bulkNorm

  def weightNormSquare: Double =
    (x * x + y * y + z * z)

  def weightNorm: Double =
    Math.sqrt(weightNormSquare)

  def normalizedByWeight =
    this / weightNorm

  def normSquare: Double =
    (w * w + x * x + y * y + z * z)

  def norm: Double =
    Math.sqrt(normSquare)

  def normalizedByNorm =
    this / norm

  @targetName("times")
  def *(r: Double): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = r * x,
      y = r * y,
      z = r * z,
      w = r * w,
    )

  /** multiplies by the reciprocal: one division instead of one per component, at the cost of one extra rounding (~0.5 ulp) */
  @targetName("div")
  def /(r: Double): Pga3dProjectivePoint =
    this * (1.0 / r)

  @targetName("plus")
  def +(r: Pga3dProjectivePoint): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (r.x + x),
      y = (r.y + y),
      z = (r.z + z),
      w = (r.w + w),
    )

  @targetName("minus")
  def -(r: Pga3dProjectivePoint): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (x - r.x),
      y = (y - r.y),
      z = (z - r.z),
      w = (w - r.w),
    )

  def madd(r: Pga3dProjectivePoint, mult: Double): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (x + mult * r.x),
      y = (y + mult * r.y),
      z = (z + mult * r.z),
      w = (w + mult * r.w),
    )

  @targetName("plus")
  def +(r: Pga3dPoint): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (r.x + x),
      y = (r.y + y),
      z = (r.z + z),
      w = (1.0 + w),
    )

  @targetName("minus")
  def -(r: Pga3dPoint): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (x - r.x),
      y = (y - r.y),
      z = (z - r.z),
      w = (-1.0 + w),
    )

  def madd(r: Pga3dPoint, mult: Double): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (x + mult * r.x),
      y = (y + mult * r.y),
      z = (z + mult * r.z),
      w = (mult + w),
    )

  @targetName("plus")
  def +(r: Pga3dVector): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (r.x + x),
      y = (r.y + y),
      z = (r.z + z),
      w = w,
    )

  @targetName("minus")
  def -(r: Pga3dVector): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (x - r.x),
      y = (y - r.y),
      z = (z - r.z),
      w = w,
    )

  def madd(r: Pga3dVector, mult: Double): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (x + mult * r.x),
      y = (y + mult * r.y),
      z = (z + mult * r.z),
      w = w,
    )

  /** componentwise product on the raw fields; NOT a geometric-algebra operation (basis-dependent) */
  def scale(r: Pga3dProjectivePoint): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = x * r.x,
      y = y * r.y,
      z = z * r.z,
      w = w * r.w,
    )

  /** componentwise 1/x on the raw fields (a zero field yields Infinity); NOT the multiplicative inverse */
  def reciprocal: Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = 1.0 / x,
      y = 1.0 / y,
      z = 1.0 / z,
      w = 1.0 / w,
    )

  def toMultivector: Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = 0.0,
      x = 0.0,
      y = 0.0,
      z = 0.0,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = -z,
      wxz = y,
      wyz = -x,
      xyz = w,
      i = 0.0,
    )

  def toVectorUnsafe: Pga3dVector =
    Pga3dVector(
      x = x,
      y = y,
      z = z,
    )

  def toPointUnsafe: Pga3dPoint =
    Pga3dPoint(
      x = x,
      y = y,
      z = z,
    )

  /** divides by the weight; an ideal point (weight == 0) yields infinite or NaN coordinates */
  def toPoint: Pga3dPoint =
    val mult = (1.0 / w)
    Pga3dPoint(
      x = mult * x,
      y = mult * y,
      z = mult * z,
    )

  /** fused plane.dot(point).geometric(plane) */
  def projectOntoPlane(plane: Pga3dPlane): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (plane.x * (-plane.w * w - plane.y * y - plane.z * z) + x * (plane.y * plane.y + plane.z * plane.z)),
      y = (plane.y * (-plane.w * w - plane.x * x - plane.z * z) + y * (plane.x * plane.x + plane.z * plane.z)),
      z = (plane.z * (-plane.w * w - plane.x * x - plane.y * y) + z * (plane.x * plane.x + plane.y * plane.y)),
      w = w * (plane.x * plane.x + plane.y * plane.y + plane.z * plane.z),
    )

  /**
   * fused -line.dot(point).geometric(line).toPointUnsafe
   * not applicable for Bivector, input should be a line
   * example of result for Bivector:
   * Pga3dMultivector(
   *   s = 0.0,
   *   w = w * (line.wy * line.xz - line.wx * line.yz - line.wz * line.xy),
   *   x = 0.0,
   *   y = 0.0,
   *   z = 0.0,
   *   wx = 0.0,
   *   wy = 0.0,
   *   wz = 0.0,
   *   xy = 0.0,
   *   xz = 0.0,
   *   yz = 0.0,
   *   wxy = (line.xy * (line.xz * y - line.xy * z - line.yz * x) + w * (-line.wx * line.xz - line.wy * line.yz)),
   *   wxz = (line.xz * (line.xz * y - line.xy * z - line.yz * x) + w * (line.wx * line.xy - line.wz * line.yz)),
   *   wyz = (line.yz * (line.xz * y - line.xy * z - line.yz * x) + w * (line.wy * line.xy + line.wz * line.xz)),
   *   xyz = w * (line.xy * line.xy + line.xz * line.xz + line.yz * line.yz),
   *   i = 0.0,
   * )
   */
  def projectOntoLine(line: Pga3dBivector): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (line.yz * (line.xy * z + line.yz * x - line.xz * y) + w * (-line.wy * line.xy - line.wz * line.xz)),
      y = (line.xz * (line.xz * y - line.xy * z - line.yz * x) + w * (line.wx * line.xy - line.wz * line.yz)),
      z = (line.xy * (line.xy * z + line.yz * x - line.xz * y) + w * (line.wx * line.xz + line.wy * line.yz)),
      w = w * (line.xy * line.xy + line.xz * line.xz + line.yz * line.yz),
    )

  infix def geometric(r: Pga3dMotor): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (r.i * w + r.xy * z + r.yz * x - r.xz * y),
      x = -r.yz * w,
      y = r.xz * w,
      z = -r.xy * w,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (-r.s * z - r.wz * w - r.xz * x - r.yz * y),
      wxz = (r.s * y + r.wy * w + r.xy * x - r.yz * z),
      wyz = (r.xy * y + r.xz * z - r.s * x - r.wx * w),
      xyz = r.s * w,
      i = 0.0,
    )

  infix def geometric(r: Pga3dPlane): Pga3dMotor =
    Pga3dMotor(
      s = 0.0,
      wx = (r.z * y - r.y * z),
      wy = (r.x * z - r.z * x),
      wz = (r.y * x - r.x * y),
      xy = r.z * w,
      xz = -r.y * w,
      yz = r.x * w,
      i = (-r.w * w - r.x * x - r.y * y - r.z * z),
    )

  infix def geometric(r: Pga3dBivector): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (r.xy * z + r.yz * x - r.xz * y),
      x = -r.yz * w,
      y = r.xz * w,
      z = -r.xy * w,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (-r.wz * w - r.xz * x - r.yz * y),
      wxz = (r.wy * w + r.xy * x - r.yz * z),
      wyz = (r.xy * y + r.xz * z - r.wx * w),
