  infix def dot(r: Pga3dBivector): Pga3dPlane =
    Pga3dPlane(
      x = -r.yz * w,
      y = r.xz * w,
      z = -r.xy * w,
      w = (r.xy * z + r.yz * x - r.xz * y),
