  inline infix def ^(r: Pga3dPlane): Pga3dPseudoScalar = wedge(r)

  inline infix def meet(r: Pga3dPlane): Pga3dPseudoScalar = wedge(r)

  infix def wedge(r: Pga3dRotor): Pga3dProjectivePoint =
