  infix def antiGeometric(r: Pga3dMotor): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (r.wx * x + r.wy * y + r.wz * z),
      x = (r.s * x + r.xy * y + r.xz * z - r.wx * w),
      y = (r.s * y + r.yz * z - r.wy * w - r.xy * x),
      z = (r.s * z - r.wz * w - r.xz * x - r.yz * y),
      wx = 0.0,
